<?php
declare(strict_types=1);
function chat_group_access(PDO $db,int $id,string $user): ?array {
 $q=$db->prepare("SELECT g.created_by,COALESCE(p.require_approval,0) require_approval,COALESCE(p.member_name,1) member_name,COALESCE(p.member_avatar,1) member_avatar,COALESCE(m.state,'active') state,COALESCE(m.role,'member') role,UNIX_TIMESTAMP(m.muted_until) muted_until,(m.muted_until>NOW()) muted FROM chat_groups g LEFT JOIN chat_group_policy p ON p.conversation_id=g.conversation_id LEFT JOIN chat_group_membership m ON m.conversation_id=g.conversation_id AND m.user_id=? WHERE g.conversation_id=?");$q->execute([$user,$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)return null;
 $r['role']=$r['created_by']===$user?'founder':$r['role'];$r['manager']=$r['state']==='active'&&in_array($r['role'],['founder','admin'],true);$r['can_write']=$r['state']==='active'&&!$r['muted'];foreach(['require_approval','member_name','member_avatar','muted'] as $k)$r[$k]=(bool)$r[$k];
 $r['reason']=in_array($r['state'],['invited','ignored'],true)?'Zaakceptuj zaproszenie, aby dołączyć do grupy.':($r['state']==='removed'?'Zostałeś usunięty z grupy. Rozmowa jest tylko do odczytu.':($r['state']==='left'?'Opuściłeś grupę. Rozmowa jest tylko do odczytu.':($r['muted']?'Jesteś wyciszony w tej grupie.':'')));unset($r['created_by']);return $r;
}
function chat_group_assert(PDO $db,int $id,string $user,string $cap='write'): void {
 $r=chat_group_access($db,$id,$user);if(!$r)return;
 if(!$r['can_write'])throw new DomainException($r['reason']);
 if(in_array($cap,['name','avatar'],true)&&!$r['manager']&&!$r['member_'.$cap])throw new DomainException('Administrator wyłączył tę możliwość dla członków grupy.');
}
function chat_group_people(PDO $db,int $id): array {
 $q=$db->prepare("SELECT m.user_id,m.username,m.display_name,COALESCE(NULLIF(n.nickname,''),m.display_name) nickname,CASE WHEN g.created_by=m.user_id THEN 'founder' ELSE COALESCE(gm.role,'member') END role,COALESCE(gm.state,'active') state,UNIX_TIMESTAMP(gm.muted_until) muted_until FROM chat_members m JOIN chat_groups g ON g.conversation_id=m.conversation_id LEFT JOIN chat_group_membership gm ON gm.conversation_id=m.conversation_id AND gm.user_id=m.user_id LEFT JOIN chat_nicknames n ON n.conversation_id=m.conversation_id AND n.user_id=m.user_id WHERE m.conversation_id=? ORDER BY FIELD(role,'founder','admin','member'),m.display_name");$q->execute([$id]);return $q->fetchAll(PDO::FETCH_ASSOC);
}
function chat_group_note(PDO $db,int $id,array $actor,string $key,string $own,string $other): int {
 $db->prepare('INSERT INTO chat_messages(conversation_id,author_id,body,client_key) VALUES(?,?,?,?)')->execute([$id,$actor['id'],'',$key]);$mid=(int)$db->lastInsertId();$db->prepare('INSERT INTO chat_system_messages(message_id,kind,payload) VALUES(?,?,?)')->execute([$mid,'group_event',json_encode(['own'=>$own,'other'=>$other],JSON_UNESCAPED_UNICODE)]);$db->prepare('UPDATE chat_conversations SET updated_at=NOW() WHERE id=?')->execute([$id]);return $mid;
}
function chat_group_contact(PDO $db,string $viewer,string $username): array {
 $q=$db->prepare("SELECT peer.user_id id,peer.username,peer.display_name name,peer.is_admin,(r.state='pending') needs_consent FROM chat_members a JOIN chat_members peer ON peer.conversation_id=a.conversation_id AND peer.user_id<>a.user_id LEFT JOIN chat_groups g ON g.conversation_id=a.conversation_id LEFT JOIN chat_requests r ON r.conversation_id=a.conversation_id LEFT JOIN chat_preferences pref ON pref.conversation_id=a.conversation_id AND pref.user_id=a.user_id WHERE a.user_id=? AND peer.username=? AND g.conversation_id IS NULL AND (r.state IS NULL OR r.state IN ('accepted','pending')) AND COALESCE(pref.archived,0)=0 AND COALESCE(pref.hidden,0)=0 AND NOT EXISTS(SELECT 1 FROM chat_preferences b WHERE b.conversation_id=a.conversation_id AND b.blocked=1) LIMIT 1");$q->execute([$viewer,$username]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p)throw new DomainException('Wybierz osobę z Twoich rozmów.');return $p;
}
function chat_group_add_member(PDO $db,int $id,array $peer): void {
 $existing=$db->prepare("SELECT 1 FROM chat_members m LEFT JOIN chat_group_membership gm ON gm.conversation_id=m.conversation_id AND gm.user_id=m.user_id WHERE m.conversation_id=? AND m.user_id=? AND COALESCE(gm.state,'active')='active'");$existing->execute([$id,$peer['id']]);if($existing->fetchColumn())throw new DomainException('Ta osoba jest już w grupie.');
 $q=$db->prepare("SELECT COUNT(*) FROM chat_members m LEFT JOIN chat_group_membership gm ON gm.conversation_id=m.conversation_id AND gm.user_id=m.user_id WHERE m.conversation_id=? AND COALESCE(gm.state,'active')='active'");$q->execute([$id]);if((int)$q->fetchColumn()>=20)throw new DomainException('Grupa może liczyć do 20 osób.');
 $q=$db->prepare('SELECT 1 FROM chat_members a JOIN chat_members b ON b.conversation_id=a.conversation_id JOIN chat_preferences p ON p.conversation_id=a.conversation_id AND p.blocked=1 LEFT JOIN chat_groups g ON g.conversation_id=a.conversation_id WHERE a.user_id=? AND b.user_id IN (SELECT m.user_id FROM chat_members m LEFT JOIN chat_group_membership gm ON gm.conversation_id=m.conversation_id AND gm.user_id=m.user_id WHERE m.conversation_id=? AND COALESCE(gm.state,"active")="active") AND g.conversation_id IS NULL LIMIT 1');$q->execute([$peer['id'],$id]);if($q->fetchColumn())throw new DomainException('Blokada kontaktu uniemożliwia dodanie tej osoby.');
 $db->prepare('INSERT INTO chat_members(conversation_id,user_id,username,display_name,is_admin) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE username=VALUES(username),display_name=VALUES(display_name)')->execute([$id,$peer['id'],$peer['username'],$peer['name'],$peer['is_admin']?1:0]);
 $db->prepare("INSERT INTO chat_group_membership(conversation_id,user_id,state) VALUES(?,?,'active') ON DUPLICATE KEY UPDATE state='active',role='member',muted_until=NULL")->execute([$id,$peer['id']]);$db->prepare('UPDATE chat_preferences SET hidden=0,archived=0 WHERE conversation_id=? AND user_id=?')->execute([$id,$peer['id']]);if(!empty($peer['needs_consent']))$db->prepare("UPDATE chat_group_membership SET state='invited' WHERE conversation_id=? AND user_id=?")->execute([$id,$peer['id']]);
}
function chat_group_manage(PDO $db,int $id,array $actor,string $op,string $target,string $setting,int $value,string $key): void {
 if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new InvalidArgumentException('Nieprawidłowy identyfikator operacji.');
 $db->beginTransaction();try{
 $db->prepare('SELECT id FROM chat_conversations WHERE id=? FOR UPDATE')->execute([$id]);chat_member($db,$id,$actor['id']);$access=chat_group_access($db,$id,$actor['id']);if($access&&$access['state']==='invited'&&in_array($op,['accept_invite','ignore_invite'],true)){$db->prepare('UPDATE chat_group_membership SET state=? WHERE conversation_id=? AND user_id=?')->execute([$op==='accept_invite'?'active':'ignored',$id,$actor['id']]);if($op==='accept_invite')chat_group_note($db,$id,$actor,$key,'Dołączyłeś(aś) do grupy.','dołączył(a) do grupy.');chat_emit($db,$id);$db->commit();return;}if(!$access||$access['state']!=='active')throw new DomainException('Nie jesteś aktywnym uczestnikiem tej grupy.');
 $q=$db->prepare('SELECT id FROM chat_messages WHERE conversation_id=? AND author_id=? AND client_key=?');$q->execute([$id,$actor['id'],$key]);if($q->fetchColumn()){$db->commit();return;}
 $people=chat_group_people($db,$id);$person=null;foreach($people as $p)if($p['username']===$target)$person=$p;
 $own='';$other='';
 if($op==='leave'){
   if($access['role']==='founder'){foreach($people as $p)if($p['user_id']!==$actor['id']&&$p['state']==='active'){$db->prepare('UPDATE chat_groups SET created_by=? WHERE conversation_id=?')->execute([$p['user_id'],$id]);break;}}
   $db->prepare("INSERT INTO chat_group_membership(conversation_id,user_id,state) VALUES(?,?,'left') ON DUPLICATE KEY UPDATE state='left',muted_until=NULL")->execute([$id,$actor['id']]);$own='Opuściłeś(aś) grupę.';$other='opuścił(a) grupę.';
 }elseif($op==='invite'){
   chat_group_assert($db,$id,$actor['id']);if($person&&$person['state']==='active')throw new InvalidArgumentException('Ta osoba jest już w grupie.');$peer=chat_group_contact($db,$actor['id'],$target);
   if($access['require_approval']&&!$access['manager']){$db->prepare('INSERT INTO chat_group_invitations(conversation_id,user_id,invited_by,username,display_name,is_admin) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE invited_by=VALUES(invited_by)')->execute([$id,$peer['id'],$actor['id'],$peer['username'],$peer['name'],$peer['is_admin']?1:0]);$own='Wysłano do zatwierdzenia zaproszenie dla '.$peer['name'].'.';$other='zaproponował(a) dodanie '.$peer['name'].'.';}
   else{chat_group_add_member($db,$id,$peer);$own=(!empty($peer['needs_consent'])?'Zaprosiłeś(aś) do grupy ':'Dodałeś(aś) do grupy ').$peer['name'].'.';$other=(!empty($peer['needs_consent'])?'zaprosił(a) do grupy ':'dodał(a) do grupy ').$peer['name'].'.';}
 }else{
   if(!$access['manager'])throw new DomainException('Ta opcja jest dostępna dla administratorów grupy.');
   if($op==='settings'){
     if(!in_array($setting,['require_approval','member_name','member_avatar'],true)||!in_array($value,[0,1],true))throw new InvalidArgumentException('Nieprawidłowe ustawienie.');$db->prepare('INSERT IGNORE INTO chat_group_policy(conversation_id) VALUES(?)')->execute([$id]);$db->prepare('UPDATE chat_group_policy SET '.$setting.'=? WHERE conversation_id=?')->execute([$value,$id]);$own='Zmieniono ustawienia grupy.';$other='zmienił(a) ustawienia grupy.';
   }elseif(in_array($op,['approve','reject'],true)){
     $q=$db->prepare('SELECT user_id id,username,display_name name,is_admin,invited_by FROM chat_group_invitations WHERE conversation_id=? AND username=?');$q->execute([$id,$target]);$peer=$q->fetch(PDO::FETCH_ASSOC);if(!$peer)throw new InvalidArgumentException('To zaproszenie już nie oczekuje na zatwierdzenie.');if($op==='approve'){$contact=chat_group_contact($db,$peer['invited_by'],$peer['username']);chat_group_add_member($db,$id,$contact);}$db->prepare('DELETE FROM chat_group_invitations WHERE conversation_id=? AND user_id=?')->execute([$id,$peer['id']]);$own=($op==='approve'?'Zaakceptowano':'Odrzucono').' zaproszenie dla '.$peer['name'].'.';$other=($op==='approve'?'zaakceptował(a)':'odrzucił(a)').' zaproszenie dla '.$peer['name'].'.';
   }elseif(in_array($op,['promote','demote','remove','mute'],true)){
     if(!$person||$person['state']!=='active'||$person['user_id']===$actor['id']||$person['role']==='founder')throw new DomainException('Nie można zmienić uprawnień tej osoby.');
     if(in_array($op,['promote','demote'],true)&&$access['role']!=='founder')throw new DomainException('Tylko założyciel zarządza administratorami.');
     if(in_array($op,['remove','mute'],true)&&$person['role']==='admin'&&$access['role']!=='founder')throw new DomainException('Tylko założyciel może moderować administratora.');
     $db->prepare('INSERT IGNORE INTO chat_group_membership(conversation_id,user_id) VALUES(?,?)')->execute([$id,$person['user_id']]);
     if($op==='mute'){if($value<0||$value>10080)throw new InvalidArgumentException('Wybierz od 0 do 10080 minut.');$db->prepare('UPDATE chat_group_membership SET muted_until=IF(?=0,NULL,DATE_ADD(NOW(),INTERVAL ? MINUTE)) WHERE conversation_id=? AND user_id=?')->execute([$value,$value,$id,$person['user_id']]);$verb=$value?'wyciszył(a)':'cofnął(a) wyciszenie';$own=($value?'Wyciszyłeś(aś) ':'Cofnąłeś(aś) wyciszenie ').$person['nickname'].($value?' na '.$value.' min.':'.');$other=$verb.' '.$person['nickname'].($value?' na '.$value.' min.':'.');}
     else{$column=$op==='remove'?'state':'role';$v=$op==='remove'?'removed':($op==='promote'?'admin':'member');$db->prepare('UPDATE chat_group_membership SET '.$column.'=? WHERE conversation_id=? AND user_id=?')->execute([$v,$id,$person['user_id']]);$own=match($op){'remove'=>'Usunąłeś(aś) z grupy ','promote'=>'Awansowałeś(aś) do administratora ',default=>'Odebrałeś(aś) uprawnienia administratora '};$other=match($op){'remove'=>'usunął(a) z grupy ','promote'=>'awansował(a) do administratora ',default=>'odebrał(a) uprawnienia administratora '};$own.=$person['nickname'].'.';$other.=$person['nickname'].'.';}
   }else throw new InvalidArgumentException('Nieznana operacja grupy.');
 }
 $db->prepare('DELETE FROM chat_typing WHERE conversation_id=?')->execute([$id]);chat_group_note($db,$id,$actor,$key,$own,$other);chat_emit($db,$id);$db->commit();
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
